        border-radius: 999px;
        background: var(--text);
        color: var(--bg);
        padding: 0.75rem 1rem;
        font-weight: 700;
      }

      .skip-link:focus {
        transform: translateY(0);
      }

      .app-shell {
        width: min(100% - 2rem, 72rem);
        margin: 0 auto;
        padding: 2rem 0 4rem;
