        align-items: center;
        gap: 0.75rem;
        color: var(--text);
        font-size: 1.05rem;
        font-weight: 800;
        letter-spacing: 0.04em;
        text-decoration: none;
        text-transform: uppercase;
      }

      .brand-mark {
        display: grid;
        width: 2.5rem;
        height: 2.5rem;
        place-items: center;
        border: 1px solid var(--border);
        border-radius: 0.85rem;
        background: linear-gradient(145deg, #24304a, #111722);
        color: var(--accent);
      }

      nav ul {
        display: flex;
        flex-wrap: wrap;
        gap: 0.75rem;
        margin: 0;
        padding: 0;
        list-style: none;
      }

      nav a {
        border-radius: 999px;
        color: var(--muted);
        padding: 0.5rem 0.75rem;
        text-decoration: none;
      }

      nav a:hover {
        color: var(--text);
      }

      main {
        display: grid;
        gap: 1.25rem;
      }

      .eyebrow {
        margin: 0;
        color: var(--accent);
        font-size: 0.82rem;
        font-weight: 800;
        letter-spacing: 0.16em;
        text-transform: uppercase;
      }

      h1,
      h2,
      p {
        overflow-wrap: anywhere;
