        max-width: 42rem;
        margin: 0;
        color: var(--muted);
        font-size: 1.08rem;
      }

      .preview-card {
        display: grid;
        grid-template-columns: minmax(0, 1.35fr) minmax(16rem, 0.65fr);
        gap: 1.25rem;
        align-items: stretch;
        margin-top: 1rem;
      }

      .image-frame,
      .details-panel {
        border: 1px solid var(--border);
        border-radius: 1.5rem;
        background: linear-gradient(180deg, var(--panel-strong), var(--panel));
        box-shadow: 0 1.5rem 5rem var(--shadow);
      }

      .image-frame {
        min-width: 0;
        overflow: hidden;
      }

      .image-frame img {
        display: block;
        width: 100%;
        max-width: 100%;
        height: auto;
      }

      .details-panel {
        display: flex;
        flex-direction: column;
        justify-content: space-between;
        gap: 2rem;
        padding: clamp(1.1rem, 4vw, 1.75rem);
      }

      .meta-list {
        display: grid;
        gap: 0.9rem;
        margin: 1.5rem 0 0;
      }

      .meta-row {
        display: flex;
        justify-content: space-between;
        gap: 1rem;
        border-bottom: 1px solid var(--border);
        padding-bottom: 0.85rem;
      }

      .meta-row dt {
        color: var(--muted);
      }

      .meta-row dd {
        margin: 0;
        color: var(--text);
        font-weight: 700;
        text-align: right;
      }

      .button-row {
        display: flex;
        flex-wrap: wrap;
        gap: 0.75rem;
      }

      button {
        min-height: 2.75rem;
        border: 1px solid transparent;
        border-radius: 999px;
        cursor: pointer;
        padding: 0.75rem 1.05rem;
        color: var(--text);
        font: inherit;
        font-weight: 800;
      }

      button:hover {
        transform: translateY(-1px);
      }

      button:active {
        transform: translateY(0);
      }

      .secondary-button {
        border-color: var(--border);
        background: #1a2333;
      }

      .trigger,
      .danger-button {
        border-color: #ff9ba4;
        background: linear-gradient(180deg, #b51d31, #7d1322);
      }

      .trigger:hover,
      .danger-button:hover {
        background: linear-gradient(180deg, #cf253b, #8f1929);
      }

      .status-message {
        min-height: 1.5rem;
        margin: 0;
        color: var(--danger-strong);
        font-weight: 700;
      }

      dialog {
        width: min(100% - 2rem, 31rem);
        border: 1px solid var(--border);
        border-radius: 1.35rem;
        background: var(--panel);
        color: var(--text);
        padding: 0;
        box-shadow: 0 2rem 7rem var(--shadow);
      }

      dialog::backdrop {
        background: #02040bcc;
        backdrop-filter: blur(0.35rem);
      }

      .dialog-content {
        display: grid;
        gap: 1rem;
        padding: clamp(1.2rem, 5vw, 2rem);
      }

      .dialog-icon {
        display: grid;
        width: 3rem;
        height: 3rem;
        place-items: center;
        border: 1px solid #ff9ba4;
        border-radius: 50%;
        background: #3a1018;
        color: var(--danger-strong);
        font-size: 1.35rem;
        font-weight: 900;
      }

      .dialog-content h2 {
        margin: 0;
        font-size: clamp(1.45rem, 6vw, 2rem);
        line-height: 1.1;
      }

      .dialog-content p {
        margin: 0;
        color: var(--muted);
      }

      .dialog-actions {
        display: flex;
        flex-wrap: wrap-reverse;
        justify-content: flex-end;
        gap: 0.75rem;
        margin-top: 0.5rem;
      }

      :focus-visible {
        outline: 3px solid transparent;
        box-shadow: 0 0 0 0.2rem var(--bg), 0 0 0 0.42rem var(--focus);
      }

      @media (max-width: 48rem) {
        header,
        .preview-card {
          grid-template-columns: 1fr;
        }

        header {
          align-items: flex-start;
          flex-direction: column;
        }
      }

      @media (max-width: 24rem) {
        .app-shell {
          width: min(100% - 1rem, 72rem);
          padding-top: 1rem;
        }

        .button-row,
        .dialog-actions {
          align-items: stretch;
          flex-direction: column;
        }

        button {
          width: 100%;
        }
